import { test, beforeEach } from "node:test";
import assert from "node:assert/strict";
import { createSession, getSession, resetSessions } from "../src/auth/session.ts";
import { refreshSession } from "../src/auth/refresh.ts";

beforeEach(() => resetSessions());

test("refreshSession issues a new session for the same user", () => {
  const old = createSession("u_1");
  const next = refreshSession(old.token);
  assert.ok(next);
  assert.equal(next.userId, "u_1");
  assert.notEqual(next.token, old.token);
  assert.equal(getSession(next.token)?.userId, "u_1");
});

test("refreshSession revokes the old token", () => {
  const old = createSession("u_2");
  const next = refreshSession(old.token);
  assert.ok(next);
  assert.equal(getSession(old.token), undefined);
  assert.equal(getSession(next.token)?.token, next.token);
});

test("refreshSession returns undefined for an unknown token", () => {
  assert.equal(refreshSession("nope"), undefined);
});

